      SUBROUTINE FIND10CC     FIND CONSTRAINT OR STORAGE ELEMENT TO WHICH ALGEBRAIC C     OPERATION MIGHT APPLYCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'INDPAR.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA      INTEGER         TYPET      EXTERNAL        IDATACC---------------------------------------------------------------------C      NN = NUM   10 NN = NN + 1      II = ISTOR(NN)      TYPET = IABS(IDATA(II))      IF (TYPET .EQ. 22 .OR. TYPET .EQ. 23) GO TO 10      IF (TYPET .EQ. 30) THEN        NEXT = IABS(IDATA(ISTOR(NN+1)))        IF (NEXT .EQ. 10 .OR. NEXT .EQ. 33 .OR. NEXT .EQ. 38) GO TO 10      ENDIF      IF (IDATA(II) .LT. 0) GO TO 100      IF (TYPET .NE. 38) THEN        IF (MKG) THEN          CALL SKETCH(NN)          IF (TYPET .EQ. 10) ID = 7          IF (TYPET .EQ. 33) ID = 2          IPT = IPTOJ(ID)          IF (IPT .EQ. 0) GO TO 100          NMARKT = IDATA(II+IPT)          MKDO = NMARKS .EQ. NMARKT          IF (.NOT. MKDO) GO TO 100        ENDIF      ENDIF   50 DRC = .TRUE.      GO TO 200C  100 NUM = NN      I = II      TYPE = -10      DRC = .FALSE.      CALL DEPICTC  200 RETURN      END